T.update({
 'DVY': ('حدود صد شرکت آمریکایی با سود نقدی بالا که وزنشان بر اساس سودی است که می‌پردازند، نه اندازه‌شان.',
         'شرکت‌هایی با سابقه طولانی پرداخت سود را انتخاب و بر اساس سود وزن‌دهی می‌کند؛ همین صندوق را به سمت شرکت‌های برق، بانک‌ها و دخانیات می‌برد. بازده نقدی‌اش از بازار بیشتر است اما تقریباً سهم فناوری ندارد و وقتی سهام رشدی جلو می‌افتند خیلی عقب می‌ماند.'),
 'SDY': ('شرکت‌های آمریکایی که دست‌کم بیست سال پیاپی سود نقدی‌شان را بالا برده‌اند، با وزن بر اساس بازده.',
         'از کل شاخص اس‌اند‌پی ۱۵۰۰ انتخاب می‌کند، پس شرکت‌های متوسط و کوچک هم دارد و به پربازده‌ترها وزن بیشتری می‌دهد. قانون بیست سال شرکت‌های جوان و هر کسی را که در بحران سودش را بریده کنار می‌گذارد.'),
 'NOBL': ('شرکت‌های اس‌اند‌پی ۵۰۰ که دست‌کم ۲۵ سال پیاپی سود نقدی را بالا برده‌اند، با وزن برابر.',
          'حدود شصت «اشراف سود نقدی» را با وزن یکسان نگه می‌دارد و هر فصل متعادل می‌کند. این کار آن را به سمت صنعتی‌ها و کالاهای اساسی می‌برد و از غول‌های فناوری که بر شاخص مسلط‌اند دور می‌کند.'),
 'HDV': ('هفتاد و پنج شرکت آمریکایی با سود نقدی بالا که از نظر سلامت مالی غربال شده‌اند.',
         'سهام پربازده را می‌گیرد و فقط آن‌هایی را نگه می‌دارد که مورنینگ‌استار از نظر مالی قوی و سودشان را پایدار می‌داند. نتیجه تمرکز در انرژی، سلامت و کالاهای اساسی است و چند غول مثل اکسون و جانسون اند جانسون سهم بزرگی دارند.'),
 'SPYD': ('هشتاد شرکت پربازده‌ترین اس‌اند‌پی ۵۰۰، با وزن برابر.',
          'شاخص را فقط بر اساس بازده نقدی مرتب می‌کند و هشتاد شرکت اول را به‌طور مساوی نگه می‌دارد. هیچ فیلتر کیفیتی ندارد، پس املاک، شرکت‌های برق و شرکت‌هایی که بازده بالایشان از ریزش قیمت سهم آمده سنگین‌اند.'),
 'DIVO': ('حدود ۲۵ شرکت بزرگ پرداخت‌کننده سود، که روی بعضی از آن‌ها برای درآمد بیشتر اختیار خرید فروخته می‌شود.',
          'مدیران شرکت‌های محکم سودده را انتخاب می‌کنند و اختیار خرید کوتاه‌مدت را گزینشی می‌فروشند نه روی کل صندوق؛ پس بخش بیشتری از رشد را نسبت به صندوقی که روی همه چیز اختیار می‌فروشد نگه می‌دارد. درآمد هم از سود نقدی است هم از حق اختیار.'),
 'QYLD': ('نزدک ۱۰۰ با فروش ماهانه اختیار خرید به قیمت روز: توزیع ماهانه بالا در ازای تقریباً همه رشد.',
          'نزدک ۱۰۰ را نگه می‌دارد و هر ماه روی کل شاخص اختیار خرید به قیمت فعلی می‌فروشد. حق اختیار توزیع بزرگی را تأمین می‌کند، اما هر رشد سقف دارد و هر ریزش کامل حس می‌شود؛ برای همین قیمت سهم صندوق در طول زمان پایین آمده است.'),
 'QQQM': ('همان نزدک ۱۰۰ صندوق QQQ، در کلاسی ارزان‌تر برای سرمایه‌گذار بلندمدت.',
          'دقیقاً همان دارایی‌های QQQ را با کارمزد سالانه کمتر دارد. QQQ به خاطر نقدشوندگی بسیار بالا انتخاب معامله‌گران و بازار اختیار است؛ برای کسی که می‌خرد و نگه می‌دارد، QQQM ارزان‌تر است.'),
 'SPYG': ('نیمه رشدی اس‌اند‌پی ۵۰۰ با هزینه بسیار کم.',
          'شاخص بر اساس رشد فروش و سود و مومنتوم تقسیم می‌شود و این صندوق سمت رشد را نگه می‌دارد. در عمل همان چند غول فناوری QQQ بر آن مسلط‌اند.'),
 'VONG': ('شاخص رشد راسل ۱۰۰۰، همان شاخص IWF، با کارمزد کمتر.',
          'نیمه رشدی هزار شرکت بزرگ آمریکا را نگه می‌دارد. راه ارزان‌تری برای داشتن همان چیزی است که IWF دارد.'),
 'IGV': ('شرکت‌های نرم‌افزاری آمریکای شمالی، از مایکروسافت و اوراکل تا شرکت‌های کوچک‌تر ابری.',
         'فقط نرم‌افزار دارد، بدون تراشه و سخت‌افزار، و وزن بزرگ‌ترها را حدود یک‌دهم صندوق محدود می‌کند. بیشترین حساسیت را به این سؤال دارد که هوش مصنوعی به شرکت‌های نرم‌افزاری کمک می‌کند یا ضربه می‌زند.'),
 'FTEC': ('شرکت‌های فناوری آمریکا در همه اندازه‌ها با یکی از کمترین کارمزدهای این بخش.',
          'همان حوزه VGT را، با شرکت‌های کوچک، پوشش می‌دهد و سقف‌هایی دارد که نمی‌گذارد بزرگ‌ترین نام‌ها از حد صندوق متنوع بیشتر شوند. تفاوتش با VGT بیشتر کارمزد و کارگزار است.'),
 'TQQQ': ('سه برابر حرکت روزانه نزدک ۱۰۰: ابزار معامله، نه سرمایه‌گذاری بلندمدت.',
          'با سوآپ و قرارداد آتی سه برابر بازده روزانه نزدک ۱۰۰ را هدف می‌گیرد و هر شب از نو تنظیم می‌شود. در چند هفته نتیجه می‌تواند خیلی با سه برابر شاخص فاصله بگیرد و در بازار نوسانی یا نزولی این تنظیم روزانه ارزش را می‌خورد؛ ریزش ۳۳ درصدی شاخص در یک روز آن را صفر می‌کند.'),
 'SOXL': ('سه برابر حرکت روزانه یک شاخص نیمه‌هادی: از پرنوسان‌ترین صندوق‌های قابل خرید.',
          'با سوآپ سه برابر بازده روزانه سی شرکت بزرگ تراشه را هدف می‌گیرد و هر روز از نو تنظیم می‌شود. سهام تراشه خودش پرنوسان است و با سه برابر کردن، ضررهای بزرگ عادی است؛ برای چند روز ساخته شده، نه چند سال.'),
 'SPYV': ('نیمه ارزشی اس‌اند‌پی ۵۰۰، ارزان: بانک‌ها، سلامت، انرژی و صنعت.',
          'شرکت‌هایی از شاخص را نگه می‌دارد که با ارزش دفتری، سود و فروش ارزان به نظر می‌رسند. برکشایر هاتاوی، جی‌پی‌مورگان و اکسون از دارایی‌های معمول آن‌اند و وقتی چند غول فناوری بازار را می‌کشند عقب می‌ماند.'),
 'VOE': ('شرکت‌های متوسط آمریکایی با ارزش‌گذاری پایین: بیمه‌ها، شرکت‌های برق، تأمین‌کنندگان صنعتی.',
         'نیمه ارزشی بازار شرکت‌های متوسط را برمی‌دارد. این شرکت‌ها کمتر خبرساز می‌شوند و همین بخشی از دلیل ارزان ماندنشان در تاریخ بوده است.'),
 'VBR': ('شرکت‌های کوچک و ارزان آمریکا: گوشه‌ای از بازار که صرف ارزش اول بار آنجا اندازه گرفته شد.',
         'حدود ۸۵۰ شرکت کوچک را که با چند معیار ارزان‌اند نگه می‌دارد. گسترده و کم‌هزینه است اما شرکت‌های زیان‌ده را حذف نمی‌کند و تفاوت اصلی‌اش با AVUV همین است.'),
 'AVUV': ('شرکت‌های کوچک، ارزان و سودده آمریکا، انتخاب‌شده با قاعده نه با سهم‌چینی.',
          'آوانتیس شرکت‌های کوچک را با نسبت قیمت به ارزش دفتری پایین و سودآوری بالا غربال می‌کند و صبورانه معامله می‌کند. فیلتر سودآوری شرکت‌هایی را که به دلیلی ارزان‌اند و صندوق‌های ارزشی ساده را پایین می‌کشند کنار می‌گذارد.'),
 'IWR': ('حدود ۸۰۰ شرکت متوسط آمریکا، از رتبه ۲۰۱ تا ۱۰۰۰ از نظر اندازه.',
         'بخش کوچک‌تر راسل ۱۰۰۰ را بدون دویست شرکت بزرگ نگه می‌دارد. شرکت‌های متوسط از پرریسک‌ترین مرحله گذشته‌اند اما هنوز جای رشد دارند.'),
 'IWO': ('نیمه رشدی راسل ۲۰۰۰: شرکت‌های جوان زیست‌فناوری، نرم‌افزار و صنعت.',
         'بسیاری از شرکت‌هایش هنوز سودده نیستند و همین آن را به یکی از حساس‌ترین صندوق‌ها به نرخ بهره و حال‌وهوای ریسک تبدیل می‌کند. رشدها موجی‌اند و ریزش‌ها می‌توانند عمیق باشند.'),
 'IWN': ('نیمه ارزشی راسل ۲۰۰۰: بانک‌های منطقه‌ای، املاک و انرژی.',
         'شرکت‌های کوچک ارزان‌تر راسل ۲۰۰۰ را نگه می‌دارد. بانک‌های منطقه‌ای سهم بزرگی دارند، پس در فشار بانکی ضربه سختی می‌خورد و وقتی اقتصاد جان می‌گیرد خوب عمل می‌کند.'),
 'MDY': ('شاخص شرکت‌های متوسط اس‌اند‌پی ۴۰۰ در قدیمی‌ترین صندوق شرکت‌های متوسط.',
         'همان ۴۰۰ شرکت IJH را دارد که کارمزدش خیلی کمتر است. به خاطر نقدشوندگی و بازار اختیار هنوز بین معامله‌گران محبوب است.'),
 'SCHA': ('حدود ۱۷۰۰ شرکت کوچک آمریکا با کارمزد بسیار کم.',
          'بخش شرکت‌های کوچک شاخص کل بازار داوجونز را نگه می‌دارد که از راسل ۲۰۰۰ گسترده‌تر است. سود را غربال نمی‌کند، پس همان دنباله ضعیف IWM را دارد.'),
 'VXF': ('همه سهام آمریکا به جز اس‌اند‌پی ۵۰۰: شرکت‌های متوسط و کوچکی که سبد را کامل می‌کنند.',
         'حدود ۳۵۰۰ شرکت بیرون از اس‌اند‌پی ۵۰۰ را بر اساس اندازه نگه می‌دارد. کنار VOO با نسبت تقریبی یک به چهار، کل بازار را می‌سازد.'),
 'VDE': ('شرکت‌های نفت و گاز آمریکا در همه اندازه‌ها، ارزان.',
         'اکسون و شورون را با وزن محدود و فهرست بلندی از تولیدکنندگان، پالایشگاه‌ها و شرکت‌های خدماتی نگه می‌دارد. نسبت به XLE شرکت کوچک بیشتر و وزن کمتری برای دو غول دارد.'),
 'VFH': ('بانک‌ها، بیمه‌ها، شبکه‌های پرداخت و مدیران دارایی آمریکا در همه اندازه‌ها.',
         'همان حوزه XLF را پوشش می‌دهد اما صدها بانک و بیمه کوچک هم اضافه می‌کند. وقتی حاشیه بهره و وام‌دهی قوی است سود می‌برد و در ترس‌های اعتباری ضرر می‌کند.'),
 'VIS': ('شرکت‌های صنعتی آمریکا: هوافضا، ماشین‌آلات، راه‌آهن، مصالح ساختمانی.',
         'حدود ۴۰۰ شرکت صنعتی دارد، خیلی بیشتر از XLI، پس کمتر به چند غول مثل جی‌ای اِروسپیس و کاترپیلار وابسته است. چرخه اقتصاد و سرمایه‌گذاری شرکت‌ها را دنبال می‌کند.'),
 'VCR': ('چیزهایی که آمریکایی‌ها وقتی پول اضافه دارند می‌خرند: خودرو، خرده‌فروشی، رستوران، سفر.',
         'آمازون و تسلا با سقف وزنی سهم بزرگی دارند و بعد زنجیره‌های لوازم خانه، رستوران‌ها و هتل‌ها. شرطی روی قدرت خرید مصرف‌کننده آمریکایی است.'),
 'VDC': ('نیازهای روزمره: مواد غذایی، لوازم خانه، نوشیدنی و دخانیات.',
         'والمارت، کاستکو و پراکتر اند گمبل در صدر بخشی‌اند که فروشش در رکود هم تقریباً تکان نمی‌خورد. در ریزش‌ها کمتر از بازار پایین می‌آید و در دوره‌های رونق عقب می‌ماند.'),
 'VPU': ('شرکت‌های برق، گاز و آب آمریکا.',
         'شرکت‌های تحت نظارت با سود نقدی پایدار که حالا شرطی روی برق موردنیاز مراکز داده هم هستند. چون زیاد وام می‌گیرند و زیاد سود می‌دهند، قیمتشان خلاف جهت نرخ بهره حرکت می‌کند.'),
 'URA': ('معدنکاران اورانیوم و شرکت‌های سوخت هسته‌ای در جهان.',
         'کامیکو و کازاتم‌پروم در صدرند، کنار صندوق‌های اورانیوم فیزیکی و تأمین‌کنندگان رآکتور. قیمت اورانیوم و حال‌وهوای سیاسی نسبت به انرژی هسته‌ای را دنبال می‌کند که هر دو می‌توانند تند تغییر کنند.'),
 'COPX': ('شرکت‌های معدن مس جهان.',
          'معدنکارانی از کانادا، استرالیا، چین و آمریکا مثل فری‌پورت‌مک‌موران را نگه می‌دارد. معدنکاران حرکت قیمت مس را بزرگ‌تر می‌کنند و مس هم به ساخت‌وساز چین، شبکه برق و خودروی برقی وابسته است.'),
 'LIT': ('معدنکاران لیتیوم و سازندگان باتری، از آلبمارل تا تولیدکنندگان چینی سلول.',
         'زنجیره باتری را از لیتیوم خام تا سلول نهایی پوشش می‌دهد و وزن چین در آن زیاد است. قیمت لیتیوم و تقاضای خودروی برقی را دنبال می‌کند که هر دو چرخه‌های عمیق رونق و سقوط داشته‌اند.'),
 'TAN': ('سازندگان پنل خورشیدی، نصاب‌ها و شرکت‌های اینورتر.',
         'فرست سولار، انفیز و دیگر شرکت‌های خورشیدی جهان را دارد. این بخش به نرخ بهره، یارانه‌ها و قیمت پنل چینی بسیار حساس است و همین آن را به یکی از پرنوسان‌ترین صندوق‌های سهام تبدیل کرده است.'),
 'PAVE': ('شرکت‌های آمریکایی که جاده، شبکه برق و کارخانه می‌سازند یا تجهیزاتش را تأمین می‌کنند.',
          'شرکت‌های ساختمانی، سازندگان تجهیزات، فولاد و تأمین‌کنندگان برقی را نگه می‌دارد که از هزینه دولتی زیرساخت و کارخانه‌سازی سود می‌برند. مثل یک صندوق صنعتی متمرکز رفتار می‌کند.'),
 'BOTZ': ('شرکت‌های رباتیک، خودکارسازی و سخت‌افزار هوش مصنوعی در جهان.',
          'انویدیا کنار سازندگان ژاپنی ربات صنعتی و شرکت‌های ربات جراحی نشسته است. نگاهی باریک‌تر و جهانی‌تر به خودکارسازی از یک صندوق فناوری معمولی.'),
 'JETS': ('شرکت‌های هواپیمایی آمریکا و خارج، به‌علاوه سازندگان هواپیما و فرودگاه‌ها.',
          'شرکت‌های بزرگ هواپیمایی آمریکا غالب‌اند و سهم کمتری به هواپیمایی‌های خارجی و شرکت‌های سفر می‌رسد. هواپیمایی‌ها به قیمت سوخت و اقتصاد وابسته‌اند و بارها به نجات دولتی نیاز داشته‌اند: صندوقی چرخه‌ای برای معامله.'),
 'KWEB': ('غول‌های اینترنتی چین: تنسنت، علی‌بابا، پی‌دی‌دی، میتوان و دیگران.',
          'شرکت‌های اینترنتی چینی پذیرفته در هنگ‌کنگ و نیویورک را نگه می‌دارد. در سخت‌گیری‌های نظارتی پکن از ۲۰۲۱ بیشتر ارزشش را از دست داد و با خبرهای سیاستی چین و آمریکا تند حرکت می‌کند.'),
 'ITB': ('خانه‌سازان آمریکا و شرکت‌هایی که به آن‌ها تأمین می‌دهند.',
         'دی‌آر هورتون، لنار و پولت‌گروپ سهم بزرگی دارند و بعد شرکت‌های مصالح و فروشگاه‌های لوازم خانه. بیش از هر چیز با نرخ وام مسکن حرکت می‌کند.'),
 'XME': ('شرکت‌های فولاد، آلومینیوم، زغال‌سنگ، طلا و مس آمریکا با وزن تقریباً برابر.',
         'وزن برابر به تولیدکنندگان کوچک همان اندازه بزرگ‌ها اهمیت می‌دهد، پس شرطی گسترده روی قیمت فلزات در آمریکاست. با تعرفه و هزینه زیرساخت می‌جهد و در کندی اقتصاد سخت می‌ریزد.'),
 'EWG': ('شرکت‌های بزرگ آلمان: اس‌اِی‌پی، زیمنس، آلیانز، دویچه تلکام.',
         'حدود شصت شرکت آلمانی با وزن زیاد در صنعت، مالی و نرم‌افزار دارد. برای سرمایه‌گذار دلاری بازده به یورو هم بستگی دارد.'),
 'EWT': ('بورس تایوان که بیشترش تی‌اس‌ام‌سی و زنجیره تأمین آن است.',
         'تی‌اس‌ام‌سی با وزن محدود بزرگ‌ترین دارایی است و بعد مدیاتک و سازندگان الکترونیک. در عمل شرطی روی چرخه جهانی تراشه به‌علاوه ریسک ژئوپلیتیک تایوان است.'),
 'EWY': ('شرکت‌های بزرگ کره جنوبی، با سامسونگ الکترونیکس و اس‌کی هاینیکس در صدر.',
         'تراشه حافظه سهم بزرگی دارد و بعد خودروسازان، بانک‌ها و سازندگان باتری. سهام کره مدت‌هاست به خاطر هلدینگ‌های خانوادگی و بازده ضعیف به سهامداران با تخفیف معامله می‌شود.'),
 'EWU': ('شرکت‌های بزرگ بریتانیا: شل، آسترازنکا، اچ‌اس‌بی‌سی، یونیلیور.',
         'بازار بریتانیا در نفت، بانک، معدن و کالاهای اساسی سنگین و در فناوری سبک است؛ برای همین ارزان معامله می‌شود و سود نقدی بالایی می‌دهد.'),
 'SPDW': ('هزاران شرکت در اروپا، ژاپن، کانادا و استرالیا با کارمزد بسیار کم.',
          'بازارهای توسعه‌یافته بیرون از آمریکا را، با شرکت‌های کوچک و کانادا، پوشش می‌دهد. جایگزین ارزانی برای VEA و SCHF با تقریباً همان شرکت‌هاست.'),
 'VGLT': ('اوراق خزانه با سررسید بیش از ده سال، با کارمزدی کمتر از TLT.',
          'اوراق دولتی بلندمدت با میانگین سررسید کمی کوتاه‌تر از TLT دارد، پس کمی کمتر به نرخ بهره حساس است. وقتی نرخ بلندمدت پایین می‌آید بالا می‌رود و برعکس.'),
 'GOVT': ('همه سررسیدهای اوراق خزانه آمریکا در یک صندوق.',
          'بازار خزانه از یک تا سی سال را به نسبت حجم انتشار نگه می‌دارد. از نظر ریسک بین صندوق‌های کوتاه و بلند است و راهی ساده برای داشتن منحنی بدهی دولت آمریکاست.'),
 'EMB': ('اوراق دلاری دولت‌های بازارهای نوظهور و شرکت‌های دولتی آن‌ها.',
         'اوراق کشورهایی مثل مکزیک، عربستان و اندونزی را دارد که به دلار پرداخت می‌شوند، پس ریسک ارزی ندارد. به خاطر ریسک نکول از اوراق خزانه بازده بیشتری دارد و وقتی دلار و نرخ بهره آمریکا با هم بالا می‌روند ضرر می‌کند.'),
 'SCHP': ('اوراق خزانه محافظت‌شده در برابر تورم، با کارمزد بسیار کم.',
          'اصل هر ورقه با شاخص قیمت مصرف‌کننده بالا می‌رود، پس در برابر غافلگیری تورمی محافظت می‌کند. با این حال وقتی نرخ بهره واقعی بالا می‌رود، مثل ۲۰۲۲، پایین می‌آید.'),
 'VGSH': ('اوراق خزانه یک تا سه ساله: همزاد ارزان SHY.',
          'اوراق دولتی کوتاه‌مدت دارد، پس قیمتش با نرخ بهره خیلی کم تکان می‌خورد. یک قدم فراتر از پول نقد برای پولی که شاید یکی دو سال دیگر لازم شود.'),
})
